commands:
"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$target = Join-Path (Get-Location) '"'community_events_sample.csv'
if (Test-Path -LiteralPath "'$target) { throw '"'目标文件已存在，停止以避免覆盖。' }
"'$csv = @'"'
活动名称,日期,名额,地点,活动说明,数据性质
【虚构】星芽社区读书会,2026-11-07,20,【虚构】星芽社区阅览室,虚构活动：分享一本喜欢的书；仅用于导入测试,虚构测试数据
【虚构】云朵社区手工坊,2026-11-14,12,【虚构】云朵社区活动室,\"虚构活动：制作纸艺作品,交流创意；仅用于导入测试\",虚构测试数据
【虚构】月湾社区棋趣日,2026-11-21,30,【虚构】月湾社区多功能厅,虚构活动：体验棋类游戏；仅用于导入测试,虚构测试数据
'@
"'$csv = $csv -replace "`r?`n", "`r`n"
[System.IO.File]::WriteAllText($target, $csv + "`r`n", [System.Text.UTF8Encoding]::new($true))
$rows = @(Import-Csv -LiteralPath $target -Encoding UTF8)
if ($rows.Count -ne 3) { throw '"'数据行数错误' }
foreach ("'$row in $rows) {
 if ($row.活动名称 -notlike '"'【虚构】*' -or "'$row.数据性质 -ne '"'虚构测试数据') { throw '虚构标识缺失' }
 "'$parsedDate = [datetime]::ParseExact($row.日期, '"'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
 if ([int]"'$row.名额 -le 0) { throw '"'名额必须为正整数' }
 if (@("'$row.PSObject.Properties).Count -ne 6) { throw '"'列数错误' }
}
Write-Output '已生成 community_events_sample.csv；重新解析验证通过：3 条活动、6 列、有效日期及正整数名额。'"
